entity_id, // Optional\n        expires_at: expiresIn * 1000 + new Date().getTime() // the expiration timestamp\n      },\n      user\n    );\n    console.log(cred);\n\n    const authenticatedUser = await Auth.currentAuthenticatedUser();\n\n    console.log(authenticatedUser);\n  } catch (err) {\n    console.log(err);\n  }\n}\n"})}),(0,o.jsx)(c,{children:(0,o.jsxs)(n.p,{children:["このメソッドの後に取得するユーザーはCognito ユーザープールからのユーザーではなく、",(0,o.jsx)(n.em,{children:"Cognito ユーザー"}),"ではないことに注意してください。"]})}),(0,o.jsx)(n.h3,{id:"facebook-サインイン-react",children:"Facebook サインイン (React)"}),(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-js",children:"import React, { useEffect } from 'react';\nimport { Auth } from 'aws-amplify';\n// To federated sign in from Facebook\nconst SignInWithFacebook = () => {\n  useEffect(() => {\n    if (!window.FB) createScript();\n  }, []);\n\n  const signIn = () => {\n    const fb = window.FB;\n    fb.getLoginStatus((response) => {\n      if (response.status === 'connected') {\n        getAWSCredentials(response.authResponse);\n      } else {\n        fb.login(\n          (response) => {\n            if (!response || !response.authResponse) {\n              return;\n            }\n            getAWSCredentials(response.authResponse);\n          },\n          {\n            // the authorized scopes\n            scope: 'public_profile,email'\n          }\n        );\n      }\n    });\n  };\n\n  const getAWSCredentials = (response) => {\n    const { accessToken, expiresIn } = response;\n    const date = new Date();\n    const expires_at = expiresIn * 1000 + date.getTime();\n    if (!accessToken) {\n      return;\n    }\n\n    const fb = window.FB;\n    fb.api('/me', { fields: 'name,email' }, (response) => {\n      const user = {\n        name: response.name,\n        email: response.email\n      };\n\n      getCognitoCredentials(\n        'facebook',\n        { token: accessToken, expires_at },\n        user\n      );\n    });\n  };\n\n  const getCognitoCredentials = async (providerName, federateOptions, user) => {\n    try {\n      const credentials = await Auth.federatedSignIn(\n        providerName,\n        federateOptions,\n        user\n      );\n      console.log(credentials);\n    } catch (err) {\n      console.log(err);\n    }\n  };\n\n  const createScript = () => {\n    // load the sdk\n    window.fbAsyncInit = fbAsyncInit;\n    const script = document.createElement('script');\n    script.src = 'https://connect.facebook.net/en_US/sdk.js';\n    script.async = true;\n    script.onload = initFB;\n    document.body.appendChild(script);\n  };\n\n  const initFB = () => {\n    const fb = window.FB;\n    console.log('FB SDK initialized');\n  };\n\n  const fbAsyncInit = () => {\n    // init the fb sdk client\n    const fb = window.FB;\n    fb.init({\n      appId: 'your_facebook_app_id',\n      cookie: true,\n      xfbml: true,\n      version: 'v2.11'\n    });\n  };\n\n  return (\n    <div>\n      <button onClick={signIn}>Sign in with Facebook</button>\n    </div>\n  );\n};\n"})}),(0,o.jsx)(n.h3,{id:"facebook-サインイン-react-native---expo",children:"Facebook サインイン (React Native - Expo)"}),(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-javascript",children:"import Expo from 'expo';\nimport React from 'react';\nimport { Amplify, Auth } from 'aws-amplify';\n\nconst App = () => {\n  const signIn = async () => {\n    const { type, token, expires } =\n      await Expo.Facebook.logInWithReadPermissionsAsync(\n        'YOUR_FACEBOOK_APP_ID',\n        {\n          permissions: ['public_profile']\n        }\n      );\n    if (type === 'success') {\n      // sign in with federated identity\n      try {\n        const credentials = await Auth.federatedSignIn(\n          'facebook',\n          { token, expires_at: expires },\n          { name: 'USER_NAME' }\n        );\n        console.log('get aws credentials', credentials);\n      } catch (err) {\n        console.log(err);\n      }\n    }\n  };\n\n  // ..